from __future__ import annotations

import json


def _split_path(path):
    return [part for part in str(path).split('.') if part]


def _get_path(value, path):
    current = value
    for part in _split_path(path):
        if isinstance(current, dict):
            current = current[part]
        elif isinstance(current, list):
            current = current[int(part)]
        else:
            raise KeyError(part)
    return current


def _format_value(value):
    if isinstance(value, str):
        return value
    if isinstance(value, (int, float, bool)) or value is None:
        return str(value)
    return json.dumps(value, ensure_ascii=False, separators=(',', ':'))


def _normalize_fields(payload):
    fields = payload.get('fields')
    if not fields:
        query = str(payload.get('query') or '').strip()
        if not query:
            raise ValueError('json.report_lines requires fields or query')
        return [{'label': str(payload.get('label') or query), 'query': query}]
    normalized = []
    for item in fields:
        query = str(item.get('query') or item.get('path') or '').strip()
        if not query:
            raise ValueError('json.report_lines field requires query')
        normalized.append({'label': str(item.get('label') or item.get('name') or query), 'query': query})
    return normalized


def run(payload, context):
    sandbox = context['sandbox']
    action = str(payload.get('action', '')).strip().lower()
    if action != 'report_lines':
        raise ValueError(f'unsupported action: {action}')
    path = str(payload.get('path') or '').strip()
    output_path = str(payload.get('output_path') or '').strip()
    if not path or not output_path:
        raise ValueError('json.report_lines requires path and output_path')
    rows = [json.loads(line) for line in sandbox.read_text(path).splitlines() if line.strip()]
    values = {}
    lines = []
    for field in _normalize_fields(payload):
        field_values = [_get_path(row, field['query']) for row in rows]
        values[field['label']] = field_values
        lines.append(f"{field['label']}: {', '.join(_format_value(value) for value in field_values)}")
    content = '\n'.join(lines) + '\n'
    sandbox.write_text(output_path, content, overwrite=bool(payload.get('overwrite', True)))
    return {'success': True, 'status': 'completed', 'message': f'JSON lines report written: {output_path}', 'output': {'valid': True, 'value': values, 'formatted': content, 'line_count': len(rows), 'errors': [], 'path': output_path, 'source_path': path}}
